from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

new_section='''<section id="shortages" class="view"><div class="top"><div><div class="brand">النواقص والطلبات</div><div class="sub">سجل مستمر حسب القسم والمقاس</div></div><button class="btn ghost" onclick="home()">الرئيسية</button></div><div class="grid"><div class="card wide"><div class="fields"><div class="field"><label>القسم</label><select id="shortSection" onchange="shortSectionChanged()"></select></div><div class="field"><label>مسؤول القسم / مكتشف النقص</label><select id="shortReporter"></select></div></div><div id="shortLegacyBox"><div class="scroll"><table><thead><tr><th>المقاس</th><th>الموجود</th><th>المطلوب للتغذية</th><th>الفرص الضائعة</th></tr></thead><tbody id="shortInput"></tbody></table></div><button class="btn ghost" onclick="addShortRow()">إضافة مقاس</button> <button class="btn" onclick="saveShortages()">حفظ النواقص</button></div><div id="shortFakherBox" class="hidden"><div class="notice ok"><b>تجربة البحث الذكي — الفاخر</b><div style="margin-top:5px">اكتب المقاس أو اللون، ثم اختر الصنف المقصود وأدخل الكميات فقط.</div></div><div class="field"><label>ابحث عن الصنف / المقاس / اللون</label><input id="fakherSearch" oninput="renderFakherResults()" placeholder="مثال: 56 أو 56S أو أبيض"></div><div id="fakherResults" style="margin-top:10px"></div><div id="fakherSelected" class="task hidden"><b id="fakherChosenLabel">—</b><div class="mut" style="margin-top:5px">فاخر • رجالي</div><div class="fields" style="margin-top:10px"><div class="field"><label>الموجود حاليًا</label><input id="fakherCurrent" inputmode="numeric" value="0"></div><div class="field"><label>المطلوب للتغذية</label><input id="fakherRequested" inputmode="numeric" value="0"></div><div class="field"><label>الفرص الضائعة</label><input id="fakherLost" inputmode="numeric" value="0"></div></div><div class="actions" style="justify-content:flex-start"><button class="btn" onclick="addFakherDraft()">إضافة للنواقص</button></div></div><div class="title" style="margin-top:18px">طلب الفاخر الحالي</div><div id="fakherDraftList"><p class="mut">لم تتم إضافة أصناف بعد.</p></div><div class="actions"><span></span><button class="btn gold" onclick="saveFakherShortages()">حفظ نواقص الفاخر</button></div></div></div><div class="card wide"><div class="title">السجل</div><div id="shortFilters" class="actions" style="justify-content:flex-start;flex-wrap:wrap"></div><div id="shortList"></div></div></div></section>'''

s,n=re.subn(r'<section id="shortages" class="view">.*?</section>\n<section id="actions"',new_section+'\n<section id="actions"',s,count=1,flags=re.S)
assert n==1,'shortages section not found'

old_state='let app={},activePlan=null,shortagesData=[],shortageSectionFilter="",rosterLoaded=null;'
new_state='let app={},activePlan=null,shortagesData=[],shortageSectionFilter="",rosterLoaded=null,fakherSelectedItem=null,fakherDraft=[];'
assert old_state in s,'global state marker not found'
s=s.replace(old_state,new_state,1)

catalog="""const FAKHER_SIZES=['53L','53M','53S','53XL','54L','54M','54S','54XL','55L','55M','55S','55XL','56L','56M','56S','56XL','56XXL','57L','57M','57S','57XL','57XXL','58L','58M','58S','58XL','58XXL','59L','59M','59S','59XL','59XXL','60L','60M','60S','60XL','60XXL','60XXXL','61L','61M','61XL','61XXL','62L','62M','62XL','62XXL','62XXXL','64L','64XL','64XXL','64XXXL','64XXXXL'];const FAKHER_COLORS=[{label:'أبيض',en:'white'},{label:'سكري',en:'cream'}];const FAKHER_CATALOG=FAKHER_SIZES.flatMap(size=>FAKHER_COLORS.map(color=>({size,color:color.label,label:`${size} — ${color.label}`,search:`${size} ${color.label} ${color.en} فاخر fakher رجالي men`})));FAKHER_CATALOG.forEach((x,i)=>x.i=i);"""
marker="const $=x=>document.getElementById(x);"
assert marker in s,'JS marker not found'
s=s.replace(marker,catalog+marker,1)

pattern=r"async function openShortages\(\)\{.*?\}function addShortRow\(\)"
replacement=r'''async function openShortages(){show('shortages');shortageSectionFilter='';fakherSelectedItem=null;fakherDraft=[];$('shortSection').innerHTML='<option value="">اختر</option>'+app.sections.filter(s=>s.display_order<=10).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');$('shortReporter').innerHTML=empOptions();$('shortInput').innerHTML='';addShortRow();shortagesData=await api('shortages');shortSectionChanged();renderShortages()}function shortSectionChanged(){let sec=app.sections.find(s=>s.id===$('shortSection').value),isFakher=sec?.name==='الفاخر';$('shortLegacyBox').classList.toggle('hidden',isFakher);$('shortFakherBox').classList.toggle('hidden',!isFakher);if(isFakher){fakherSelectedItem=null;$('fakherSelected').classList.add('hidden');$('fakherSearch').value='';$('fakherResults').innerHTML='<p class="mut">ابدأ بالكتابة للبحث في مقاسات وألوان الفاخر.</p>';renderFakherDraft()}}function renderFakherResults(){let q=$('fakherSearch').value.trim().toLowerCase();if(!q){$('fakherResults').innerHTML='<p class="mut">ابدأ بالكتابة للبحث في مقاسات وألوان الفاخر.</p>';return}let rows=FAKHER_CATALOG.filter(x=>x.search.toLowerCase().includes(q)).slice(0,16);$('fakherResults').innerHTML=rows.length?'<div class="actions" style="justify-content:flex-start;flex-wrap:wrap">'+rows.map(x=>`<button class="mini" onclick="selectFakherItem(${x.i})">${esc(x.label)}</button>`).join('')+'</div>':'<div class="notice">لا توجد نتيجة مطابقة في نموذج الفاخر.</div>'}function selectFakherItem(i){let x=FAKHER_CATALOG[i];if(!x)return;let section=$('shortSection').value,key=x.label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)return alert(`هذا الصنف له طلب تغذية قائم بالفعل.\nالحالة: تم الطلب — قيد المتابعة\nتاريخ الطلب: ${dup.ordered_date||'—'}`);fakherSelectedItem=x;$('fakherChosenLabel').textContent=x.label;$('fakherCurrent').value='0';$('fakherRequested').value='0';$('fakherLost').value='0';$('fakherSelected').classList.remove('hidden')}function addFakherDraft(){try{if(!fakherSelectedItem)throw Error('اختر الصنف أولًا');let label=fakherSelectedItem.label;if(fakherDraft.some(x=>x.label===label))throw Error('هذا الصنف مضاف بالفعل في الطلب الحالي');let current=Number($('fakherCurrent').value||0),requested=Number($('fakherRequested').value||0),lost=Number($('fakherLost').value||0);if([current,requested,lost].some(x=>Number.isNaN(x)||x<0))throw Error('أدخل الكميات بشكل صحيح');fakherDraft.push({label,size:fakherSelectedItem.size,color:fakherSelectedItem.color,current_qty:current,requested_qty:requested,lost_opportunities:lost});renderFakherDraft();fakherSelectedItem=null;$('fakherSelected').classList.add('hidden');$('fakherSearch').value='';$('fakherResults').innerHTML='<p class="mut">تمت الإضافة. ابحث عن صنف آخر أو احفظ الطلب.</p>'}catch(e){alert(e.message)}}function removeFakherDraft(i){fakherDraft.splice(i,1);renderFakherDraft()}function renderFakherDraft(){$('fakherDraftList').innerHTML=fakherDraft.length?fakherDraft.map((x,i)=>`<div class="task"><b>${esc(x.label)}</b><div class="mut" style="margin-top:6px">الموجود: ${x.current_qty} | المطلوب: ${x.requested_qty} | الفرص الضائعة: ${x.lost_opportunities}</div><div style="margin-top:8px"><button class="mini" style="color:#c83b3b;border-color:#efb4b4" onclick="removeFakherDraft(${i})">حذف</button></div></div>`).join(''):'<p class="mut">لم تتم إضافة أصناف بعد.</p>'}function addShortRow()'''
s,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
assert n==1,'openShortages block not found'

insert_before='function setShortageFilter(id)'
smart_save=r'''async function saveFakherShortages(){try{let section=$('shortSection').value,sec=app.sections.find(s=>s.id===section);if(sec?.name!=='الفاخر')throw Error('اختر قسم الفاخر');if(!fakherDraft.length)throw Error('أضف صنفًا واحدًا على الأقل');for(const row of fakherDraft){let key=row.label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)throw Error(`يوجد طلب قائم للصنف ${row.label} منذ ${dup.ordered_date||'—'}`)}await api('shortage-save',{method:'POST',body:{section_id:section,reporter_employee_id:$('shortReporter').value,rows:fakherDraft.map(x=>({size:x.label,current_qty:x.current_qty,requested_qty:x.requested_qty,lost_opportunities:x.lost_opportunities}))}});fakherDraft=[];fakherSelectedItem=null;shortagesData=await api('shortages');renderFakherDraft();renderShortages();alert('تم حفظ نواقص الفاخر')}catch(e){alert(e.message)}}'''
assert insert_before in s,'filter marker not found'
s=s.replace(insert_before,smart_save+insert_before,1)

marker='<!-- pages-publish: fakher-smart-shortage-search-2026-08-24 -->'
s=re.sub(r'<!-- pages-publish: [^>]+ -->',marker,s,count=1)
if marker not in s:
    s=s.replace('<title>ركيزة V1</title>','<title>ركيزة V1</title>'+marker,1)

p.write_text(s,encoding='utf-8')
